// Service worker check (CLAUDE.md "PWA cache", Codex review 2 M4). Part of `npm run check`: runs after
// the build together with size.mjs (`npm run size -w apps/web`). Also alone: `npm run check:sw -w apps/web`.
//
// Reads dist/sw.js (generated by vite-plugin-pwa / Workbox) and fails (closed) when
//   - it holds anything but the reviewed Workbox statements (message listener, precache, cleanup, routes),
//   - anything in it queues, answers or caches requests by itself (background sync, a default handler,
//     a fetch listener, Cache Storage), or a precached URL belongs to another origin,
//   - the precache is not literal ({url, revision} entries outside /api/ and /auth/callback) or takes an
//     option generateSW does not write (urlManipulation …), or a no-argument statement gets arguments,
//   - a runtime-caching route has a matcher the check cannot read (only regex literals and same-origin
//     paths, GET only), would match Supabase (REST /rest/, auth /auth/, *.supabase.co) or another origin,
//     or is anchored at the start of the URL (^ / lookbehind: only a cross-origin route needs that),
//   - the navigation fallback (index.html) does not leave /auth/callback and /api/ to the network.
// Also (size, not security): nothing of the home-screen icon variants (public/icons/variants/, ≈ 1.1 MB) is precached —
// a device fetches only the icon it chose (Einstellungen → App-Symbol, vite.config.ts globIgnores). And nothing of the
// comic «Pompon & Tapsi» (its reader chunk and translations, assets/comic-*.js): it loads only when someone opens it.
// The rules live in scripts/sw-rules.mjs (unit-tested in src/test/swCheck.test.ts and
// src/test/attack/round1-sw-headers.test.tsx, round2-sw-headers.test.ts). Exit code 1 on a problem.

import { existsSync, readdirSync, readFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { analyzePushWorker, analyzeServiceWorker, importedScripts } from './sw-rules.mjs'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const swPath = resolve(root, 'dist', 'sw.js')

if (!existsSync(swPath)) {
  console.error(`check-sw: ${swPath} not found — run "npm run build" first`)
  process.exit(1)
}

const sw = readFileSync(swPath, 'utf8')
const { problems, runtimeRoutes, denylist } = analyzeServiceWorker(sw)
const precached = [...sw.matchAll(/\burl:"([^"]*)"/g)].map((match) => match[1])
for (const url of precached.filter((entry) => /(?:^|\/)icons\/variants\//.test(entry))) {
  problems.push(`precaches the home-screen icon variant file ${url} (only the chosen one is fetched, on demand — vite.config.ts globIgnores)`)
}
for (const url of precached.filter((entry) => /(?:^|\/)assets\/comic-[^/]*$/.test(entry))) {
  problems.push(`precaches the comic file ${url} (it is fetched only when someone opens the comic — vite.config.ts globIgnores)`)
}
// fail closed on a real build: the reader's chunk + its 4 translations must still be named comic-*.js (vite.config.ts
// COMIC_ENTRY), or the rule above would check nothing (a crafted dist/sw.js without assets, as in the tests, skips this)
const assetsDir = resolve(root, 'dist', 'assets')
const comicFiles = existsSync(assetsDir) ? readdirSync(assetsDir).filter((file) => /^comic-.*\.js$/.test(file)) : []
if (existsSync(assetsDir) && comicFiles.length < 5) problems.push(`expected the comic reader chunk + 4 translations as assets/comic-*.js, found ${comicFiles.length} (vite.config.ts COMIC_ENTRY)`)
// Web Push (docs/spec/web-push-design.md §8): every script sw.js imports is checked too — it must exist in dist and
// hold only the reviewed push / notificationclick listeners (sw-rules.mjs analyzePushWorker)
const imported = importedScripts(sw)
for (const path of imported) {
  const file = resolve(root, 'dist', path.replace(/^\//, ''))
  if (!existsSync(file)) problems.push(`sw.js imports ${path}, but dist has no such file (the service worker would fail to install)`)
  else problems.push(...analyzePushWorker(readFileSync(file, 'utf8')).map((problem) => `${path}: ${problem}`))
}

console.log(`\nService worker (dist/sw.js): ${runtimeRoutes} runtime-caching route(s); navigation fallback denylist ${denylist.join(' ') || '—'}`)
if (problems.length > 0) {
  for (const problem of problems) console.error(`check-sw: ${problem}`)
  console.error('check-sw: the service worker breaks the PWA cache rules (CLAUDE.md "PWA cache", vite.config.ts workbox)')
  process.exit(1)
}
console.log(`check-sw: ${precached.length} precached file(s), none of the home-screen icon variants, none of the ${comicFiles.length} comic files (assets/comic-*.js)`)
if (imported.length > 0) console.log(`check-sw: imports ${imported.join(', ')} — only the reviewed push listeners, no network, no cache`)
console.log('check-sw: only the reviewed Workbox setup; no Supabase REST/auth in the service worker caches, nothing queued; /auth/callback and /api/ bypass the fallback')
